arguments.content:
const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Our World in Data";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";
pres.subject = "Global CO₂ emissions from fossil fuels and industry, 1750–2024";

// ============================================================
// COLOR PALETTE: Ocean Gradient (adapted for climate/data-forward tone)
// Primary deep navy: 1A2F4B
// Secondary teal: 2E8B8B
// Accent coral/salmon: E07A5F
// Light background: F4F7F9
// Dark background: 1A2F4B
// Muted text: 5A6B7C
// White: FFFFFF
// ============================================================
const C = {
  primary: "1A2F4B",
  secondary: "2E8B8B",
  accent: "E07A5F",
  light: "F4F7F9",
  dark: "1A2F4B",
  muted: "5A6B7C",
  white: "FFFFFF",
  grid: "D1D9E0",
  chart1: "1A2F4B",
  chart2: "2E8B8B",
  chart3: "E07A5F",
  chart4: "5A6B7C",
  chart5: "8FB9C1",
  chart6: "D4A373",
  chart7: "81B29A",
  chart8: "F2CC8F",
};

const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri Light";

function makeShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

// ============================================================
// SLIDE 1: Title
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Decorative accent bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.12, h: 5.625,
    fill: { color: C.accent }, line: { style: "none" }
  });

  // Title
  slide.addText("Global CO₂ Emissions", {
    x: 0.7, y: 1.6, w: 8.5, h: 0.9,
    fontSize: 44, fontFace: FONT_HEAD, bold: true, color: C.white,
    align: "left", valign: "middle", margin: 0
  });

  // Subtitle
  slide.addText("Who Emits, How Much, and What's Changing", {
    x: 0.7, y: 2.5, w: 8.5, h: 0.5,
    fontSize: 24, fontFace: FONT_BODY, color: C.white,
    align: "left", valign: "middle", margin: 0
  });

  // Scope line
  slide.addText("Fossil fuels & industry · 1750–2024", {
    x: 0.7, y: 3.2, w: 8.5, h: 0.35,
    fontSize: 16, fontFace: FONT_BODY, color: C.accent,
    align: "left", valign: "middle", margin: 0
  });

  // Source attribution
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.7, y: 4.8, w: 8.5, h: 0.3,
    fontSize: 11, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });

  // Audience context
  slide.addText("For policy analysts, climate negotiators & sustainability researchers", {
    x: 0.7, y: 5.05, w: 8.5, h: 0.3,
    fontSize: 11, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 2: Global Emissions Growth (line/area chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  // Title
  slide.addText("Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 28, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Chart data: approximate trajectory based on source brief
  const years = ["1750", "1850", "1900", "1950", "1970", "1990", "2000", "2010", "2020", "2024"];
  const values = [0.01, 0.2, 1.9, 6.0, 14.0, 22.5, 25.5, 33.0, 34.5, 36.0];

  slide.addChart(pres.charts.LINE, [{
    name: "Global CO₂ (Bt)",
    labels: years,
    values: values
  }], {
    x: 0.5, y: 1.1, w: 9, h: 3.6,
    chartColors: [C.accent],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    lineSize: 3,
    lineSmooth: true,
    showLegend: false,
    showValue: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 40,
    valAxisTitle: "Billion tonnes CO₂",
    catAxisTitle: "Year",
    title: "",
    dataLabelPosition: "top",
    dataLabelColor: C.dark,
    dataLabelFontSize: 10,
  });

  // Annotation callouts
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.85, w: 2.8, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("Pre-industrial: negligible", {
    x: 0.7, y: 4.9, w: 2.6, h: 0.45,
    fontSize: 11, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.8, y: 4.85, w: 2.8, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("Post-1950: rapid acceleration", {
    x: 3.9, y: 4.9, w: 2.6, h: 0.45,
    fontSize: 11, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.0, y: 4.85, w: 2.4, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("Today: >35 Bt, no peak yet", {
    x: 7.1, y: 4.9, w: 2.2, h: 0.45,
    fontSize: 11, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Footer source
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.45, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 3: Regional Share Shift (stacked area chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 26, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Stacked area chart showing regional shares over time
  const shareYears = ["1900", "1950", "1980", "2000", "2010", "2024"];
  slide.addChart(pres.charts.AREA, [
    { name: "Europe + US", labels: shareYears, values: [92, 86, 55, 38, 30, 28] },
    { name: "Asia (incl. China)", labels: shareYears, values: [5, 8, 25, 38, 45, 50] },
    { name: "Rest of World", labels: shareYears, values: [3, 6, 20, 24, 25, 22] }
  ], {
    x: 0.5, y: 1.1, w: 9, h: 3.6,
    chartColors: [C.chart1, C.chart3, C.chart5],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendColor: C.dark,
    legendFontSize: 10,
    showValue: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 100,
    valAxisTitle: "Share of global CO₂ (%)",
    catAxisTitle: "",
    lineSize: 2,
  });

  // Key stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 4.2, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("In 1900, Europe + US >90%. Today Asia alone ≈50%.", {
    x: 0.6, y: 4.9, w: 4.0, h: 0.45,
    fontSize: 12, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.45, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 4: China Dominates Share (treemap-style bar chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("China Now Emits More Than One-Quarter of Global CO₂", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 28, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Horizontal bar chart for country shares
  const countries = ["China", "United States", "India", "EU-27", "Russia", "Africa", "South America", "Int'l aviation & shipping", "Rest of World"];
  const shares = [31, 13, 8, 6, 5, 3.5, 3.5, 3, 26.5];
  const barColors = [C.accent, C.chart1, C.chart2, C.chart4, C.chart5, C.chart6, C.chart7, C.chart8, C.grid];

  slide.addChart(pres.charts.BAR, [{
    name: "Share of global CO₂ (2024)",
    labels: countries,
    values: shares
  }], {
    x: 0.5, y: 1.1, w: 9, h: 3.6,
    barDir: "bar",
    chartColors: barColors,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.dark,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.dark,
    dataLabelFontSize: 10,
    valAxisMinVal: 0,
    valAxisMaxVal: 35,
    valAxisTitle: "% of global CO₂",
    catAxisTitle: "",
  });

  // Trend annotations
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 2.8, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("China ~31% (rising, slowing)", {
    x: 0.6, y: 4.9, w: 2.6, h: 0.45,
    fontSize: 11, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.6, y: 4.85, w: 2.8, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("US ~13% (declining)", {
    x: 3.7, y: 4.9, w: 2.6, h: 0.45,
    fontSize: 11, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 4.85, w: 2.8, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("India ~8% (rising)", {
    x: 6.8, y: 4.9, w: 2.6, h: 0.45,
    fontSize: 11, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.45, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 5: Per Capita Inequality (horizontal bar chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Per Capita Emissions Range from 0.1 t in Chad to ~14 t in the US and Canada", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 26, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  const pcCountries = ["United States", "Canada", "China", "South Africa", "EU-27", "World avg", "UK", "India", "Kenya", "Chad / Niger"];
  const pcValues = [14, 14, 9, 7, 6, 4.5, 4, 2, 0.4, 0.1];
  const pcColors = [C.accent, C.accent, C.chart3, C.chart6, C.chart2, C.chart4, C.chart5, C.chart7, C.chart8, C.chart1];

  slide.addChart(pres.charts.BAR, [{
    name: "Per capita CO₂ (t)",
    labels: pcCountries,
    values: pcValues
  }], {
    x: 0.5, y: 1.1, w: 9, h: 3.6,
    barDir: "bar",
    chartColors: pcColors,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.dark,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.dark,
    dataLabelFontSize: 10,
    valAxisMinVal: 0,
    valAxisMaxVal: 16,
    valAxisTitle: "Tonnes CO₂ per person",
    catAxisTitle: "",
  });

  // 150x gap callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 4.5, h: 0.55,
    fill: { color: C.white },
    line: { color: C.accent, size: 1.5 },
    shadow: makeShadow()
  });
  slide.addText("150× gap: an American emits in ~2 days what a person in Niger emits in a year", {
    x: 0.6, y: 4.9, w: 4.3, h: 0.45,
    fontSize: 12, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.45, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 6: Per Capita Trends Over Time (multi-line chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Per Capita Emissions Vary Widely: ~14 t in the US vs. ~9 t in China and ~2 t in India", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 24, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Multi-line chart: approximate trends for key countries
  const trendYears = ["1990", "1995", "2000", "2005", "2010", "2015", "2020", "2024"];
  slide.addChart(pres.charts.LINE, [
    { name: "United States", labels: trendYears, values: [19.5, 19.0, 19.5, 19.0, 17.0, 16.0, 14.5, 14.0] },
    { name: "China", labels: trendYears, values: [2.0, 2.5, 3.0, 5.0, 6.5, 7.5, 8.0, 9.0] },
    { name: "EU-27", labels: trendYears, values: [9.0, 8.5, 8.0, 7.5, 7.0, 6.5, 6.0, 6.0] },
    { name: "India", labels: trendYears, values: [0.8, 0.9, 1.0, 1.2, 1.5, 1.7, 1.8, 2.0] },
    { name: "World avg", labels: trendYears, values: [4.0, 4.0, 4.0, 4.2, 4.5, 4.5, 4.3, 4.5] }
  ], {
    x: 0.5, y: 1.1, w: 9, h: 3.6,
    chartColors: [C.accent, C.chart3, C.chart2, C.chart7, C.chart4],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendColor: C.dark,
    legendFontSize: 10,
    showValue: false,
    lineSize: 2.5,
    lineSmooth: true,
    valAxisMinVal: 0,
    valAxisMaxVal: 22,
    valAxisTitle: "Tonnes CO₂ per person",
    catAxisTitle: "",
  });

  // Insight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 4.5, h: 0.55,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText("China's per capita remains below the US despite being the largest total emitter", {
    x: 0.6, y: 4.9, w: 4.3, h: 0.45,
    fontSize: 12, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.45, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 7: Annual Change 2024 (diverging bar chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("2024 Snapshot: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 24, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Diverging bar chart: approximate 2024 annual % change
  const changeCountries = ["Turkmenistan/Uzbekistan", "Russia", "Southeast Asia (avg)", "Several African nations", "World avg", "UK", "EU-27", "United States"];
  const changeValues = [12, 3, 2.5, 2, 0.5, -2, -2.5, -3];
  const changeColors = changeValues.map(v => v >= 0 ? C.accent : C.secondary);

  slide.addChart(pres.charts.BAR, [{
    name: "Annual % change 2024",
    labels: changeCountries,
    values: changeValues
  }], {
    x: 0.5, y: 1.1, w: 9, h: 3.6,
    barDir: "bar",
    chartColors: changeColors,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.dark,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.dark,
    dataLabelFontSize: 10,
    valAxisMinVal: -5,
    valAxisMaxVal: 15,
    valAxisTitle: "% change in CO₂ emissions (2024)",
    catAxisTitle: "",
  });

  // Legend / key
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 1.8, h: 0.35,
    fill: { color: C.secondary }, line: { style: "none" }
  });
  slide.addText("Decline", {
    x: 0.5, y: 4.85, w: 1.8, h: 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 2.5, y: 4.85, w: 1.8, h: 0.35,
    fill: { color: C.accent }, line: { style: "none" }
  });
  slide.addText("Increase", {
    x: 2.5, y: 4.85, w: 1.8, h: 0.35,
    fontSize: 11, fontFace: FONT_BODY, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.45, w: 9, h: 0.2,
    fontSize: 9, fontFace: FONT_BODY, color: C.muted,
    align: "left", valign: "middle", margin: 0
  });
}

// ============================================================
// SLIDE 8: Energy Mix Matters (comparative bar + text)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.light };

  slide.addText("Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    fontSize: 24, fontFace: FONT_HEAD, bold: true, color: C.dark,
    align: "left", valign: "middle", margin: 0
  });

  // Left: comparative bar chart
  const energyCountries = ["United States", "Germany", "Netherlands", "EU-27 avg", "France", "UK", "Portugal"];
  const energyValues = [14, 8.5, 8, 6, 4.5, 4, 4];
  const energyColors = [C.accent, C.chart3, C.chart3, C.chart4, C.secondary, C.secondary, C.secondary];

  slide.addChart(pres.charts.BAR, [{
    name: "Per capita CO₂ (t)",
    labels: energyCountries,
    values: energyValues
  }], {
    x: 0.5, y: 1.1, w: 5.2, h: 3.6,
    barDir: "bar",
    chartColors: energyColors,
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.dark,
    valAxisLabelColor: C.muted,
    valGridLine: { color: C.grid, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.dark,
    dataLabelFontSize: 10,
    valAxisMinVal: 0,
    valAxisMaxVal: 16,
    valAxisTitle: "t CO₂ / person",
    catAxisTitle: "",
  });

  // Right: text explanation cards
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.0, y: 1.1, w: 3.5, h: 1.1,
    fill: { color: C.white },
    line: { color: C.grid, size: 0.5 },
    shadow: makeShadow()
  });
  slide.addText([
    { text: "Higher fossil share", options: { bold: true, breakLine: true } },
    { text: "US, Germany, Netherlands rely more on coal, oil, and gas for electricity and transport.", options: { breakLine: false } }
  ], {
    x: 6.1, y: 1.2, w: 3.3, h: 0.9,
    fontSize: 12, fontFace: FONT_BODY, color: C.dark,
    align: "left", valign: "top", margin: 0
  });

